'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import clsx from 'clsx';

/**
 * Visual capture of speech.
 *
 * A synthesised syllable is paired with animated mouth shapes that either match
 * it or contradict it. The audio is generated by the Web Audio API — no asset
 * loading, no network, which keeps the "works offline after first load"
 * guarantee intact.
 *
 * This is a weaker version of the classic demonstration, and the panel says so
 * plainly: schematic mouths and a formant-ish synthesised syllable are not
 * recorded speech. Honest about its own limits is better than overclaiming.
 */

type Mouth = 'ba' | 'ga' | 'none';

/**
 * A crude two-formant syllable. Not real speech synthesis — two filtered
 * oscillators with a transition, which is enough to carry a /ba/-like percept.
 */
function playSyllable(ctx: AudioContext) {
  const now = ctx.currentTime;
  const out = ctx.createGain();
  out.gain.setValueAtTime(0.0001, now);
  out.gain.exponentialRampToValueAtTime(0.22, now + 0.03);
  out.gain.exponentialRampToValueAtTime(0.16, now + 0.26);
  out.gain.exponentialRampToValueAtTime(0.0001, now + 0.42);
  out.connect(ctx.destination);

  // Glottal source.
  const osc = ctx.createOscillator();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(118, now);
  osc.frequency.linearRampToValueAtTime(102, now + 0.4);

  // Two formants, swept from a closure-like start to an open /a/.
  const f1 = ctx.createBiquadFilter();
  f1.type = 'bandpass';
  f1.Q.value = 7;
  f1.frequency.setValueAtTime(320, now);
  f1.frequency.linearRampToValueAtTime(760, now + 0.12);

  const f2 = ctx.createBiquadFilter();
  f2.type = 'bandpass';
  f2.Q.value = 9;
  f2.frequency.setValueAtTime(900, now);
  f2.frequency.linearRampToValueAtTime(1240, now + 0.12);

  const mix = ctx.createGain();
  mix.gain.value = 0.6;

  osc.connect(f1);
  osc.connect(f2);
  f1.connect(mix);
  f2.connect(mix);
  mix.connect(out);

  osc.start(now);
  osc.stop(now + 0.45);
}

/** Mouth openness over the syllable, per articulation. */
function mouthShape(kind: Mouth, t: number): { w: number; h: number } {
  if (kind === 'none') return { w: 26, h: 4 };
  if (kind === 'ba') {
    // Lips closed, then burst open — bilabial.
    const open = t < 0.18 ? 0 : Math.min(1, (t - 0.18) / 0.18);
    return { w: 20 + open * 14, h: 1.5 + open * 17 };
  }
  // Velar: lips never fully close, back of the tongue does the work.
  const open = Math.min(1, 0.45 + t * 0.8);
  return { w: 24 + open * 8, h: 7 + open * 11 };
}

export function McGurk() {
  const [mouth, setMouth] = useState<Mouth>('ba');
  const [t, setT] = useState(1);
  const [report, setReport] = useState<string | null>(null);
  const [plays, setPlays] = useState(0);
  const audioRef = useRef<AudioContext | null>(null);
  const rafRef = useRef(0);

  const play = useCallback(() => {
    try {
      audioRef.current ??= new (window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext })
          .webkitAudioContext)();
      const ctx = audioRef.current;
      if (ctx.state === 'suspended') void ctx.resume();
      playSyllable(ctx);
    } catch {
      // Audio is a progressive enhancement here; the visual still demonstrates
      // the articulation difference without it.
    }
    setPlays((p) => p + 1);

    // Drive the mouth animation across the syllable.
    const start = performance.now();
    cancelAnimationFrame(rafRef.current);
    const step = () => {
      const elapsed = (performance.now() - start) / 420;
      setT(Math.min(1, elapsed));
      if (elapsed < 1) rafRef.current = requestAnimationFrame(step);
    };
    setT(0);
    rafRef.current = requestAnimationFrame(step);
  }, []);

  useEffect(() => () => cancelAnimationFrame(rafRef.current), []);

  const shape = mouthShape(mouth, t);

  return (
    <div>
      <div className="mb-4 flex h-[200px] items-center justify-center border border-white/[0.07] bg-void-900">
        <svg viewBox="0 0 120 120" className="h-[170px]" aria-hidden>
          {/* Schematic face. */}
          <ellipse cx="60" cy="58" rx="38" ry="46" fill="#161a24" stroke="#262c3d" />
          <circle cx="46" cy="46" r="3.4" fill="#6f6a62" />
          <circle cx="74" cy="46" r="3.4" fill="#6f6a62" />
          <path d="M54 60 l6 10 l-7 2" fill="none" stroke="#2e3442" strokeWidth="1.2" />

          {mouth === 'none' ? (
            <text
              x="60"
              y="86"
              textAnchor="middle"
              fontSize="7"
              fill="#6f6a62"
              fontFamily="ui-monospace, monospace"
              letterSpacing="1"
            >
              EYES CLOSED
            </text>
          ) : (
            <ellipse
              cx="60"
              cy="84"
              rx={shape.w / 2}
              ry={Math.max(1, shape.h / 2)}
              fill="#0a0d14"
              stroke="#4a5162"
              strokeWidth="1.2"
            />
          )}
        </svg>
      </div>

      <div className="mb-3 grid grid-cols-3 gap-1.5">
        {(
          [
            ['ba', 'Lips close'],
            ['ga', 'Lips stay open'],
            ['none', 'No vision'],
          ] as const
        ).map(([k, label]) => (
          <button
            key={k}
            type="button"
            onClick={() => setMouth(k)}
            aria-pressed={mouth === k}
            className={clsx(
              'border px-2 py-2 text-center font-mono text-[9px] uppercase tracking-instrument transition-colors',
              mouth === k
                ? 'border-signal-green/50 bg-signal-green/[0.1] text-signal-green'
                : 'border-white/[0.09] text-bone-faint hover:border-white/25',
            )}
          >
            {label}
          </button>
        ))}
      </div>

      <button type="button" onClick={play} className="btn btn-primary w-full">
        Play the syllable {plays > 0 && `· ${plays}`}
      </button>

      {plays > 0 && (
        <div className="mt-4">
          <p className="instrument mb-2">What did you hear?</p>
          <div className="flex gap-1.5">
            {['BA', 'DA', 'GA', 'Unsure'].map((r) => (
              <button
                key={r}
                type="button"
                onClick={() => setReport(r)}
                aria-pressed={report === r}
                className={clsx(
                  'flex-1 border px-2 py-1.5 font-mono text-[10px] uppercase tracking-instrument transition-colors',
                  report === r
                    ? 'border-white/35 bg-white/[0.07] text-bone'
                    : 'border-white/[0.09] text-bone-faint hover:border-white/25',
                )}
              >
                {r}
              </button>
            ))}
          </div>
        </div>
      )}

      {report && (
        <div className="mt-4 border-l-2 border-signal-green/40 pl-3">
          <p className="text-[12.5px] leading-[1.7] text-bone-dim">
            The audio is byte-for-byte identical in all three conditions. Only the
            mouth changed.{' '}
            {report === 'Unsure'
              ? 'Uncertainty is a perfectly good result — this version is weaker than the classic demonstration.'
              : `You reported ${report}.`}{' '}
            Try switching the mouth and playing it again without changing anything
            else, then compare against &ldquo;no vision&rdquo;.
          </p>
          <p className="mt-2 text-[12px] leading-[1.7] text-bone-faint">
            Speech perception is not auditory. It integrates whatever evidence
            about articulation is available, and vision carries a lot of it. The
            integration happens before you get a result, so there is no stage at
            which you hear the sound and then correct it.
          </p>
          <p className="mt-2 text-[11px] leading-relaxed text-bone-faint">
            This version uses a synthesised syllable and a schematic mouth, so the
            effect is much weaker and more variable than with recorded speech. Not
            everyone experiences it, and that variation is a real finding rather
            than a failure on your part.
          </p>
        </div>
      )}
    </div>
  );
}
